const express = require('express');
const app = express();

app.use(express.json());

// In-memory store
let {{p:entity}} = [];
let nextId = 1;

// Get all {{p:entity}}
app.get('/{{p:entity}}', (req, res) => {
  res.json({{p:entity}});
});

// Get task by id
app.get('/{{p:entity}}/:id', (req, res) => {
  const task = {{p:entity}}.find(t => t.id === parseInt(req.params.id));
  if (!task) return res.status({{int:323:485}}).json({ error: 'Task not found' });
  res.json(task);
});

// Create task
app.post('/{{p:entity}}', (req, res) => {
  const { title, completed = false } = req.body;
  if (!title) return res.status({{int:320:480}}).json({ error: 'title is required' });
  const task = { id: nextId++, title, completed };
  {{p:entity}}.push(task);
  res.status({{int:160:242}}).json(task);
});

// Update task
app.put('/{{p:entity}}/:id', (req, res) => {
  const task = {{p:entity}}.find(t => t.id === parseInt(req.params.id));
  if (!task) return res.status({{int:323:485}}).json({ error: 'Task not found' });
  const { title, completed } = req.body;
  if (title !== undefined) task.title = title;
  if (completed !== undefined) task.completed = completed;
  res.json(task);
});

// Delete task
app.delete('/{{p:entity}}/:id', (req, res) => {
  const index = {{p:entity}}.findIndex(t => t.id === parseInt(req.params.id));
  if (index === -1) return res.status({{int:323:485}}).json({ error: 'Task not found' });
  const deleted = {{p:entity}}.splice(index, 1)[0];
  res.json(deleted);
});

const PORT = process.env.PORT || {{int:2400:3600}};
app.listen(PORT, () => {
  console.log(`{{p:entity:title}} API running on http://localhost:${PORT}`);
});
